unsafe extern "C" fn FindLanguageIndex(mut LanguageId: PCWSTR) -> ULONG {
    let mut lngIndex: ULONG = 0;

    if LanguageId.is_null() {
        LanguageId = RUSTCONV_WSTR_230B3B8A6763.as_ptr();
    }

    while !MUILanguageList[lngIndex as usize].LanguageID.is_null() {
        if _wcsicmp(
            MUILanguageList[lngIndex as usize].LanguageID,
            LanguageId,
        ) == 0
        {
            return lngIndex;
        }

        lngIndex = lngIndex.wrapping_add(1);
    }

    return 0;
}
#[no_mangle]
pub unsafe extern "C" fn IsLanguageAvailable(LanguageId: PCWSTR) -> i32 {
    let mut lngIndex: u32 = 0;

    while !MUILanguageList[lngIndex as usize].LanguageID.is_null() {
        if _wcsicmp(
            MUILanguageList[lngIndex as usize].LanguageID,
            LanguageId,
        ) == 0
        {
            return (TRUE) as i32;
        }

        lngIndex = lngIndex.wrapping_add(1);
    }

    return (FALSE) as i32;
}

#[no_mangle]
pub unsafe extern "C" fn MUIDefaultKeyboardLayout(LanguageId: PCWSTR) -> KLID {
    let lngIndex: ULONG = FindLanguageIndex(LanguageId);
    return (*MUILanguageList[lngIndex as usize]
        .MuiLayouts
        .offset(0 as isize))
    .LayoutID;
}

#[no_mangle]
pub unsafe extern "C" fn MUIGetOEMCodePage(LanguageId: PCWSTR) -> u32 {
    let lngIndex: u32 = FindLanguageIndex(LanguageId);
    return MUILanguageList[lngIndex as usize].OEMCPage;
}
#[no_mangle]
pub unsafe extern "C" fn MUIGetGeoID(LanguageId: PCWSTR) -> u32 {
    let lngIndex: u32 = FindLanguageIndex(LanguageId);
    return MUILanguageList[lngIndex as usize].GeoID;
}
#[no_mangle]
pub unsafe extern "C" fn MUIGetLayoutsList(
    LanguageId: PCWSTR,
) -> *const MUI_LAYOUTS {
    let lngIndex: u32 = FindLanguageIndex(LanguageId);
    return MUILanguageList[lngIndex as usize].MuiLayouts;
}

unsafe extern "C" fn AddHotkeySettings(
    Hotkey: PCWSTR,
    LangHotkey: PCWSTR,
    LayoutHotkey: PCWSTR,
) -> BOOLEAN {
    let mut ObjectAttributes: _OBJECT_ATTRIBUTES = core::mem::zeroed();
    let mut KeyName: _UNICODE_STRING = core::mem::zeroed();
    let mut ValueName: _UNICODE_STRING = core::mem::zeroed();
    let mut KeyHandle: HANDLE = core::ptr::null_mut();
    let mut Disposition: ULONG = 0;
    let mut Status: NTSTATUS = 0;

    RtlInitUnicodeString(
        &mut KeyName,
        RUSTCONV_WSTR_BD844A6914FB.as_ptr(),
    );
    InitializeObjectAttributes!(
        &mut ObjectAttributes,
        &mut KeyName,
        OBJ_CASE_INSENSITIVE,
        GetRootKeyByPredefKey((HKEY_USERS).cast(), core::ptr::null_mut()),
        core::ptr::null_mut(),
    );

    Status = NtCreateKey(
        &mut KeyHandle,
        KEY_SET_VALUE,
        &mut ObjectAttributes,
        0,
        core::ptr::null_mut(),
        REG_OPTION_NON_VOLATILE,
        &mut Disposition,
    );
    if ((NT_SUCCESS!(Status)) == 0) {
        DPRINT1!("NtCreateKey() failed (Status %lx)\n", Status);
        return (FALSE) as u8;
    }

    RtlInitUnicodeString(
        &mut ValueName,
        RUSTCONV_WSTR_D59C317D44DA.as_ptr(),
    );

    Status = NtSetValueKey(
        KeyHandle,
        &mut ValueName,
        0,
        REG_SZ,
        Hotkey as PVOID,
        (1 + 1) * core::mem::size_of::<WCHAR>() as ULONG,
    );
    if ((NT_SUCCESS!(Status)) == 0) {
        DPRINT1!("NtSetValueKey() failed (Status %lx)\n", Status);
        NtClose(KeyHandle);
        return (FALSE) as u8;
    }

    RtlInitUnicodeString(
        &mut ValueName,
        RUSTCONV_WSTR_F315F9787974.as_ptr(),
    );

    Status = NtSetValueKey(
        KeyHandle,
        &mut ValueName,
        0,
        REG_SZ,
        LangHotkey as PVOID,
        (1 + 1) * core::mem::size_of::<WCHAR>() as ULONG,
    );
    if ((NT_SUCCESS!(Status)) == 0) {
        DPRINT1!("NtSetValueKey() failed (Status %lx)\n", Status);
        NtClose(KeyHandle);
        return (FALSE) as u8;
    }

    RtlInitUnicodeString(
        &mut ValueName,
        RUSTCONV_WSTR_593117FB0799.as_ptr(),
    );

    Status = NtSetValueKey(
        KeyHandle,
        &mut ValueName,
        0,
        REG_SZ,
        LayoutHotkey as PVOID,
        (1 + 1) * core::mem::size_of::<WCHAR>() as ULONG,
    );
    if ((NT_SUCCESS!(Status)) == 0) {
        DPRINT1!("NtSetValueKey() failed (Status %lx)\n", Status);
        NtClose(KeyHandle);
        return (FALSE) as u8;
    }

    NtClose(KeyHandle);
    return (TRUE) as u8;
}
